import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.k0yuBbP4.js";const u=JSON.parse('{"title":"Plugin factory","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://zilero232.github.io/gulp-plugins-hub/reference/factory"}]]},"headers":[],"relativePath":"reference/factory.md","filePath":"reference/factory.md","lastUpdated":1792453423000}'),s={name:"reference/factory.md"};function n(r,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="plugin-factory" tabindex="-1">Plugin factory <a class="header-anchor" href="#plugin-factory" aria-label="Permalink to &quot;Plugin factory&quot;">​</a></h1><p><code>@zilero/gulp-plugin-factory</code> — the toolkit every plugin of the hub is built with. A guided tour is in <a href="/gulp-plugins-hub/guide/writing-plugins">Writing a plugin</a>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  applySourceMap,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  assertBinaryContents,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  createPlugin,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  getChainableSourceMap,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  getInputSourceMap,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  isFunction,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  isRelativePathInside,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  parseOptions,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  PluginError,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  toPluginError,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  toPosixPath,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Vinyl</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@zilero/gulp-plugin-factory&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="createplugin-definition" tabindex="-1"><code>createPlugin(definition)</code> <a class="header-anchor" href="#createplugin-definition" aria-label="Permalink to &quot;`createPlugin(definition)`&quot;">​</a></h2><p>Returns an object-mode <code>Transform</code> stream: Vinyl files in, Vinyl files out, one at a time and in order.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td>Prefixes every error; use the package name.</td></tr><tr><td><code>accept</code></td><td><code>&#39;buffer&#39; | &#39;any&#39;</code></td><td><code>&#39;buffer&#39;</code> (default): <code>transform</code> gets files with Buffer contents only. <code>&#39;any&#39;</code>: every file.</td></tr><tr><td><code>filter</code></td><td><code>(file: Vinyl) =&gt; boolean</code></td><td>Files it returns false for pass through untouched, before any other check.</td></tr><tr><td><code>transform</code></td><td><code>(file, context) =&gt; TransformResult | Promise&lt;TransformResult&gt;</code></td><td>Called for each file. Nothing: the file goes on. <code>null</code>: dropped. A file or an array: those go on instead.</td></tr><tr><td><code>flush</code></td><td><code>(context) =&gt; void | Promise&lt;void&gt;</code></td><td>Runs once after the last file, before the stream ends.</td></tr></tbody></table><p><code>context</code> is <code>{ name, push }</code>: <code>push(file)</code> sends a file downstream from <code>transform</code> or <code>flush</code>.</p><p>A <code>filter</code> that throws is reported like any other error. With <code>accept: &#39;buffer&#39;</code>, a file without contents passes through and a file with streamed contents emits <code>Streaming is not supported</code>. Anything <code>transform</code> or <code>flush</code> throws or rejects with is emitted as a <code>PluginError</code> with the plugin name and the file path (<code>fileName</code>); a <code>PluginError</code> is emitted as it is.</p><p>Types: <code>PluginDefinition</code>, <code>BufferPluginDefinition</code>, <code>AnyPluginDefinition</code>, <code>PluginContext</code>, <code>TransformResult</code>, <code>BufferFile</code> (a Vinyl file whose <code>contents</code> is a <code>Buffer</code>), <code>PluginStream</code>.</p><h2 id="parseoptions-name-schema-options" tabindex="-1"><code>parseOptions({ name, schema, options })</code> <a class="header-anchor" href="#parseoptions-name-schema-options" aria-label="Permalink to &quot;`parseOptions({ name, schema, options })`&quot;">​</a></h2><p>Validates <code>options</code> against a synchronous <a href="https://standardschema.dev" target="_blank" rel="noreferrer">Standard Schema</a> (zod 4, valibot, arktype, …) and returns the parsed value, defaults applied. Invalid options throw a <code>PluginError</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Invalid options:</span></span>\n<span class="line"><span>    • quality: Too big: expected number to be &lt;=100</span></span>\n<span class="line"><span>    • Unrecognized key: &quot;qualty&quot;</span></span></code></pre></div><p>An asynchronous schema throws <code>The options schema must be synchronous</code>.</p><h2 id="applysourcemap-file-map-chain" tabindex="-1"><code>applySourceMap({ file, map, chain? })</code> <a class="header-anchor" href="#applysourcemap-file-map-chain" aria-label="Permalink to &quot;`applySourceMap({ file, map, chain? })`&quot;">​</a></h2><p>Stores a tool&#39;s source map (an object or JSON) as <code>file.sourceMap</code>, the way <code>dest(…, { sourcemaps })</code> expects it: <code>file</code> becomes the file&#39;s relative path, absolute or <code>file://</code> sources become relative to <code>file.base</code>, and every source uses <code>/</code>. With <code>chain: true</code> the file&#39;s current map is chained into the new one first, for tools that cannot take an input map; the new map&#39;s only source must be the file itself.</p><h2 id="getchainablesourcemap-file" tabindex="-1"><code>getChainableSourceMap(file)</code> <a class="header-anchor" href="#getchainablesourcemap-file" aria-label="Permalink to &quot;`getChainableSourceMap(file)`&quot;">​</a></h2><p>The file&#39;s map with absolute sources (<code>sourceRoot</code> applied), ready to chain into another map with <code>@jridgewell/remapping</code>; gulp keeps sources relative to <code>file.base</code>, while remapping resolves them against the map they are chained into. <code>undefined</code> when there is nothing to chain.</p><h2 id="getinputsourcemap-file" tabindex="-1"><code>getInputSourceMap(file)</code> <a class="header-anchor" href="#getinputsourcemap-file" aria-label="Permalink to &quot;`getInputSourceMap(file)`&quot;">​</a></h2><p>The file&#39;s current map as JSON, to pass to a tool as its input map. <code>undefined</code> when the file has none, or has the empty map <code>src(…, { sourcemaps: true })</code> gives files without one: chaining that would leave the output map empty.</p><h2 id="assertbinarycontents-relative-contents" tabindex="-1"><code>assertBinaryContents({ relative, contents })</code> <a class="header-anchor" href="#assertbinarycontents-relative-contents" aria-label="Permalink to &quot;`assertBinaryContents({ relative, contents })`&quot;">​</a></h2><p>Throws when binary contents look like they were decoded as UTF-8 (the U+FFFD replacement character in the first 64 bytes), with the fix in the message: <code>Read binary files with `src(globs, { encoding: false })`</code>.</p><h2 id="isfunction-value" tabindex="-1"><code>isFunction(value)</code> <a class="header-anchor" href="#isfunction-value" aria-label="Permalink to &quot;`isFunction(value)`&quot;">​</a></h2><p>A type guard for option schemas: <code>z.custom&lt;Hook&gt;(isFunction, &#39;Expected a function&#39;)</code> checks a callback without wrapping it.</p><h2 id="isrelativepathinside-value" tabindex="-1"><code>isRelativePathInside(value)</code> <a class="header-anchor" href="#isrelativepathinside-value" aria-label="Permalink to &quot;`isRelativePathInside(value)`&quot;">​</a></h2><p>For option schemas: a relative path that stays inside the folder it is relative to and is not that folder. <code>css/main.css</code> passes; <code>/tmp/x</code>, <code>../x</code> and <code>.</code> do not.</p><h2 id="toposixpath-value" tabindex="-1"><code>toPosixPath(value)</code> <a class="header-anchor" href="#toposixpath-value" aria-label="Permalink to &quot;`toPosixPath(value)`&quot;">​</a></h2><p>A path with <code>/</code> separators on every OS, for globs, archive entries, manifests and source maps.</p><h2 id="topluginerror-name-error-file" tabindex="-1"><code>toPluginError({ name, error, file? })</code> <a class="header-anchor" href="#topluginerror-name-error-file" aria-label="Permalink to &quot;`toPluginError({ name, error, file? })`&quot;">​</a></h2><p>Wraps anything in a <code>PluginError</code> prefixed with <code>name</code>, with <code>fileName</code> from the file; a <code>PluginError</code> is returned as it is. <code>createPlugin</code> uses it for every error.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><ul><li><code>ContentHook</code> — <code>(input: { content: string; file: Vinyl }) =&gt; string | Promise&lt;string&gt;</code>, the hook on a file&#39;s text the plugins share.</li><li><code>SourceMap</code>, <code>BufferFile</code>, <code>PluginDefinition</code>, <code>PluginContext</code>, <code>TransformResult</code>, <code>PluginStream</code>.</li></ul><h2 id="re-exports" tabindex="-1">Re-exports <a class="header-anchor" href="#re-exports" aria-label="Permalink to &quot;Re-exports&quot;">​</a></h2><ul><li><code>PluginError</code> — the class from <a href="https://github.com/gulpjs/plugin-error" target="_blank" rel="noreferrer">plugin-error</a>.</li><li><code>Vinyl</code> — the file class from <a href="https://github.com/gulpjs/vinyl" target="_blank" rel="noreferrer">vinyl</a>, and its type: <code>import type { Vinyl } from &#39;@zilero/gulp-plugin-factory&#39;</code>.</li></ul>',33)])])}const f=a(s,[["render",n]]);export{u as __pageData,f as default};
